CREATE OR REPLACE FUNCTION public.broker_license_approved_for(_uid uuid,_number text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND _number ~ '^[1-9][0-9]{0,9}$' AND (EXISTS(SELECT 1 FROM public.admin_approved_broker_licenses a WHERE a.user_id=_uid AND a.license_number=_number) OR EXISTS(SELECT 1 FROM public.test_broker_licenses t WHERE t.user_id=_uid AND t.license_number=_number) OR EXISTS(SELECT 1 FROM public.official_brokers_registry r WHERE r.license_number=_number AND r.source_url='https://data.gov.il/dataset/d361f6a6-898c-4e4d-8a80-abc4e8643bf6' AND r.source_updated_at>now()-interval '7 days' AND r.source_updated_at<=now()+interval '1 minute' AND extract(year from r.source_updated_at)=extract(year from now()))) $$;
REVOKE ALL ON FUNCTION public.broker_license_approved_for(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.broker_license_approved_for(uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.has_verified_broker_license(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_uid AND public.broker_license_approved_for(_uid,p.broker_license_number)) $$;
CREATE OR REPLACE FUNCTION public.enforce_official_profile_license() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.broker_license_number IS DISTINCT FROM OLD.broker_license_number THEN IF NULLIF(NEW.broker_license_number,'') IS NOT NULL AND NOT public.broker_license_approved_for(NEW.id,NEW.broker_license_number) THEN RAISE EXCEPTION 'מספר הרישיון אינו תקף או אינו מופיע בפנקס המתווכים המורשים'; END IF; IF NULLIF(NEW.broker_license_number,'') IS NULL AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=NEW.id AND role IN ('agent','lead_agent','managing_broker','junior_agent')) THEN RAISE EXCEPTION 'remove_broker_license_through_authorized_action'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.partner_can_view_closing(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id IS NOT NULL AND (EXISTS(SELECT 1 FROM public.profiles p JOIN public.admin_approved_broker_licenses a ON a.user_id=p.id AND a.license_number=p.broker_license_number WHERE p.id=_user_id AND EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=p.id AND ur.role IN ('agent','lead_agent','managing_broker','junior_agent'))) OR EXISTS(SELECT 1 FROM public.official_brokers_registry r WHERE r.source_url='https://data.gov.il/dataset/d361f6a6-898c-4e4d-8a80-abc4e8643bf6' AND r.source_updated_at>now()-interval '7 days' AND r.source_updated_at<=now()+interval '1 minute' AND extract(year from r.source_updated_at)=extract(year from now()) AND (EXISTS(SELECT 1 FROM public.broker_license_verifications v JOIN public.profiles p ON p.id=v.user_id AND p.broker_license_number=v.license_number WHERE v.user_id=_user_id AND v.license_number=r.license_number AND EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=_user_id AND ur.role IN ('managing_broker','lead_agent','agent'))) OR EXISTS(SELECT 1 FROM public.affiliate_profiles ap WHERE ap.user_id=_user_id AND ap.license_status='verified' AND ap.license_number=r.license_number AND ap.license_verified_at IS NOT NULL)))) $$;
CREATE OR REPLACE FUNCTION public.affiliate_tier3_eligible(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.partner_can_view_closing(_user_id) $$;
CREATE OR REPLACE FUNCTION public.get_broker_license_state(_user_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE lic text; status text:='pending'; BEGIN IF auth.uid() IS NULL OR NOT (auth.uid()=_user_id OR public.has_role(auth.uid(),'super_admin') OR public.can_access_workspace_owner(_user_id)) THEN RAISE EXCEPTION 'not_authorized'; END IF; SELECT broker_license_number INTO lic FROM public.profiles WHERE id=_user_id; IF EXISTS(SELECT 1 FROM public.broker_license_verifications v WHERE v.user_id=_user_id AND v.license_number=lic AND v.source_url='https://data.gov.il/dataset/d361f6a6-898c-4e4d-8a80-abc4e8643bf6') THEN status:='verified'; ELSIF EXISTS(SELECT 1 FROM public.admin_approved_broker_licenses a WHERE a.user_id=_user_id AND a.license_number=lic) THEN status:='approved'; END IF; RETURN jsonb_build_object('license_number',lic,'status',status,'active',public.partner_can_view_closing(_user_id)); END $$;
REVOKE ALL ON FUNCTION public.get_broker_license_state(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_broker_license_state(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.revoke_broker_license(_uid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid:=auth.uid(); removed int; BEGIN IF actor IS NULL OR (actor<>_uid AND NOT public.has_role(actor,'super_admin')) THEN RAISE EXCEPTION 'not_authorized'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_uid::text,0)); DELETE FROM public.user_roles WHERE user_id=_uid AND role IN ('agent','lead_agent','managing_broker','junior_agent'); GET DIAGNOSTICS removed=ROW_COUNT; DELETE FROM public.admin_approved_broker_licenses WHERE user_id=_uid; DELETE FROM public.broker_license_verifications WHERE user_id=_uid; DELETE FROM public.broker_role_suspensions WHERE user_id=_uid; UPDATE public.affiliate_profiles SET license_number=NULL,license_status='none',license_verified_at=NULL WHERE user_id=_uid; UPDATE public.profiles SET broker_license_number=NULL WHERE id=_uid; INSERT INTO public.user_roles(user_id,role) VALUES(_uid,'user') ON CONFLICT(user_id,role) DO NOTHING; INSERT INTO public.audit_logs(actor_id,action,target_table,target_id,details) VALUES(actor,'broker_license_removed','profiles',_uid::text,jsonb_build_object('roles_removed',removed)); RETURN jsonb_build_object('ok',true,'roles_removed',removed); END $$;
REVOKE ALL ON FUNCTION public.revoke_broker_license(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.revoke_broker_license(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.remove_my_broker_license() RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.revoke_broker_license(auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.admin_remove_broker_license(_user_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'not_authorized'; END IF; RETURN public.revoke_broker_license(_user_id); END $$;